//! Compares plt-text's mathtext with matplotlib on the fixtures generated by
//! `tests/fixtures/mathtext/generate.py`: box metrics, the vector and raster
//! extents, every glyph position and rule, and error messages.

use std::collections::BTreeMap;
use std::fmt::Write as _;

use plt_font::{FontDatabase, FontQuery, FontSource};
use plt_text::mathtext::{CustomFonts, MathFallback, MathLayout, MathStyle, is_math_text};
use plt_text::{BlockStyle, FontRequest, LineMetrics, TextEngine, TextError, layout_block};

const CASES: &str = include_str!("fixtures/mathtext/cases.txt");

/// Relative tolerance for "close" (not bit-exact) values.
const TOLERANCE: f64 = 1e-9;

#[derive(Debug, Default)]
struct Expected {
    category: String,
    fontset: String,
    size: f64,
    dpi: f64,
    options: String,
    source: String,
    error: Option<String>,
    boxed: [f64; 3],
    vector: [f64; 3],
    raster: [f64; 3],
    glyphs: Vec<(String, u16, u32, [f64; 3])>,
    rects: Vec<[f64; 4]>,
    extent: Option<[f64; 4]>,
}

fn decode(text: &str) -> String {
    text.replace("%0A", "\n")
        .replace("%09", "\t")
        .replace("%25", "%")
}

fn floats<const N: usize>(fields: &[&str]) -> [f64; N] {
    let mut out = [0.0; N];
    for (slot, field) in out.iter_mut().zip(fields) {
        *slot = field.parse().expect("float field");
    }
    out
}

fn parse_cases() -> Vec<Expected> {
    let mut cases = Vec::new();
    let mut current = Expected::default();
    for line in CASES.lines() {
        let fields: Vec<&str> = line.split('\t').collect();
        match fields[0] {
            "case" => {
                current = Expected {
                    category: fields[1].to_owned(),
                    fontset: fields[2].to_owned(),
                    size: fields[3].parse().expect("size"),
                    dpi: fields[4].parse().expect("dpi"),
                    options: fields[5].to_owned(),
                    source: decode(fields.get(6).copied().unwrap_or("")),
                    ..Expected::default()
                };
            }
            "box" => current.boxed = floats(&fields[1..]),
            "vec" => current.vector = floats(&fields[1..]),
            "ras" => current.raster = floats(&fields[1..]),
            "g" => {
                let [size, x, y] = floats(&fields[4..]);
                current.glyphs.push((
                    fields[1].to_owned(),
                    fields[2].parse().expect("glyph"),
                    fields[3].parse().expect("code"),
                    [size, x, y],
                ));
            }
            "r" => current.rects.push(floats(&fields[1..])),
            "err" => current.error = Some(decode(fields[1])),
            "ext" => current.extent = Some(floats(&fields[1..])),
            "end" => cases.push(std::mem::take(&mut current)),
            other => panic!("unexpected fixture line kind {other:?}"),
        }
    }
    cases
}

fn style_for(case: &Expected) -> MathStyle {
    let mut style = MathStyle {
        fontset: case.fontset.parse().expect("fontset"),
        font: FontRequest::new(FontQuery {
            size: case.size,
            ..FontQuery::families(["DejaVu Sans"])
        }),
        dpi: case.dpi,
        ..MathStyle::default()
    };
    if case.options != "-" {
        let mut custom = CustomFonts::default();
        for item in case.options.split(';') {
            let (key, value) = item.split_once('=').expect("key=value");
            match key {
                "default" => style.default = value.parse().expect("font"),
                "fallback" => style.fallback = MathFallback::parse(value).expect("fallback"),
                "family" => style.font.query.families = vec![value.to_owned()],
                "rm" => value.clone_into(&mut custom.rm),
                "it" => value.clone_into(&mut custom.it),
                "bf" => value.clone_into(&mut custom.bf),
                "bfit" => value.clone_into(&mut custom.bfit),
                "sf" => value.clone_into(&mut custom.sf),
                "tt" => value.clone_into(&mut custom.tt),
                "cal" => value.clone_into(&mut custom.cal),
                other => panic!("unknown option {other}"),
            }
        }
        style.custom = custom;
    }
    style
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum Grade {
    Exact,
    Close,
    Failed,
}

#[allow(clippy::float_cmp, reason = "bit-exact agreement is what is measured")]
fn grade_value(expected: f64, actual: f64) -> Grade {
    if expected == actual || (expected.is_nan() && actual.is_nan()) {
        Grade::Exact
    } else if (expected - actual).abs() <= TOLERANCE * expected.abs().max(1.0) {
        Grade::Close
    } else {
        Grade::Failed
    }
}

fn grade_all(pairs: impl IntoIterator<Item = (f64, f64)>) -> Grade {
    pairs
        .into_iter()
        .map(|(e, a)| grade_value(e, a))
        .max()
        .unwrap_or(Grade::Exact)
}

fn file_name(db: &FontDatabase, font: plt_font::FontId) -> String {
    match db.source(font) {
        Some(FontSource::Bundled(name)) => (*name).to_owned(),
        Some(source) => source.file_name().unwrap_or_default().to_owned(),
        None => String::new(),
    }
}

/// Grades one successful case, describing the first difference.
fn compare(db: &FontDatabase, case: &Expected, layout: &MathLayout) -> (Grade, String) {
    let run = layout.to_text_run();
    let raster = layout.raster_extents();
    let boxed = grade_all(
        case.boxed
            .into_iter()
            .zip([layout.width, layout.height, layout.depth]),
    );
    if boxed == Grade::Failed {
        let actual = [layout.width, layout.height, layout.depth];
        return (Grade::Failed, format!("box {:?} != {actual:?}", case.boxed));
    }
    let vector = grade_all(
        case.vector
            .into_iter()
            .zip([run.width, run.height, run.descent]),
    );
    let raster_grade =
        grade_all(
            case.raster
                .into_iter()
                .zip([raster.width, raster.height, raster.depth]),
        );
    if vector == Grade::Failed || raster_grade == Grade::Failed {
        return (
            Grade::Failed,
            format!("extents {:?} {:?}", case.vector, case.raster),
        );
    }
    if case.glyphs.len() != run.glyphs.len() || case.rects.len() != run.rects.len() {
        return (
            Grade::Failed,
            format!(
                "{} glyphs / {} rects expected, got {} / {}",
                case.glyphs.len(),
                case.rects.len(),
                run.glyphs.len(),
                run.rects.len()
            ),
        );
    }
    let mut grade = boxed.max(vector).max(raster_grade);
    for (i, ((file, glyph, code, [size, x, y]), (actual, info))) in case
        .glyphs
        .iter()
        .zip(run.glyphs.iter().zip(&layout.glyphs))
        .enumerate()
    {
        let actual_file = file_name(db, actual.font);
        if *file != actual_file || *glyph != actual.glyph.0 || *code != info.code {
            return (
                Grade::Failed,
                format!(
                    "glyph {i}: {file} #{glyph} U+{code:x} != {actual_file} #{} U+{:x}",
                    actual.glyph.0, info.code
                ),
            );
        }
        let g = grade_all([(*size, actual.size), (*x, actual.x), (*y, actual.y)]);
        if g == Grade::Failed {
            return (
                Grade::Failed,
                format!(
                    "glyph {i} ({file} #{glyph}): {:?} != {:?}",
                    [size, x, y],
                    [actual.size, actual.x, actual.y]
                ),
            );
        }
        grade = grade.max(g);
    }
    // `Bbox` stores the far corner, so read the exact rule sizes from the
    // layout and apply VectorParse's flip.
    let top = layout.height.ceil();
    for (i, (expected, actual)) in case.rects.iter().zip(&layout.rects).enumerate() {
        let actual_values = [
            actual.x,
            top - (actual.y + actual.height),
            actual.width,
            actual.height,
        ];
        let g = grade_all(expected.iter().copied().zip(actual_values));
        if g == Grade::Failed {
            return (
                Grade::Failed,
                format!("rect {i}: {expected:?} != {actual_values:?}"),
            );
        }
        grade = grade.max(g);
    }
    (grade, String::new())
}

/// `Text(0, 0, source).get_window_extent()`: each line typeset as math or
/// plain text, stacked by the block layout.
fn text_extent(
    engine: &TextEngine,
    case: &Expected,
    style: &MathStyle,
) -> Result<[f64; 4], TextError> {
    let lines = case
        .source
        .split('\n')
        .map(|line| {
            let run = if line.is_empty() {
                return Ok(LineMetrics::default());
            } else if is_math_text(line) {
                engine.layout_math(line, style)?
            } else {
                engine.layout_line(&line.replace("\\$", "$"), &style.font, style.dpi)?
            };
            Ok(LineMetrics {
                width: run.width,
                height: run.height,
                descent: run.descent,
            })
        })
        .collect::<Result<Vec<_>, TextError>>()?;
    let font = engine.font_height_metrics(&style.font, style.dpi)?;
    let bbox = layout_block(&lines, font, &BlockStyle::default()).bbox;
    Ok([bbox.xmin(), bbox.ymin(), bbox.xmax(), bbox.ymax()])
}

#[derive(Default)]
struct Tally {
    exact: usize,
    close: usize,
    failed: usize,
}

type Tallies = BTreeMap<(String, String), Tally>;

fn record(
    tallies: &mut Tallies,
    failures: &mut Vec<String>,
    case: &Expected,
    grade: Grade,
    why: &str,
) {
    let tally = tallies
        .entry((case.category.clone(), case.fontset.clone()))
        .or_default();
    match grade {
        Grade::Exact => tally.exact += 1,
        Grade::Close => tally.close += 1,
        Grade::Failed => {
            tally.failed += 1;
            failures.push(format!(
                "[{} {} {}pt {}dpi {}] {:?}: {why}",
                case.category, case.fontset, case.size, case.dpi, case.options, case.source
            ));
        }
    }
}

#[test]
fn mathtext_matches_matplotlib() {
    let engine = TextEngine::new(FontDatabase::with_bundled_fonts());
    let db = engine.database();
    let mut tallies = Tallies::new();
    let mut failures = Vec::new();
    for case in parse_cases() {
        let style = style_for(&case);
        if let Some(expected) = case.extent {
            let (grade, why) = match text_extent(&engine, &case, &style) {
                Ok(actual) => (
                    grade_all(expected.into_iter().zip(actual)),
                    format!("extent {expected:?} != {actual:?}"),
                ),
                Err(err) => (Grade::Failed, err.to_string()),
            };
            record(&mut tallies, &mut failures, &case, grade, &why);
            continue;
        }
        let result = engine.typeset_math(&case.source, &style);
        let (grade, why) = match (&case.error, &result) {
            (Some(expected), Err(TextError::Math(actual))) if expected == actual => {
                (Grade::Exact, String::new())
            }
            (Some(_), Err(TextError::Math(_))) => (Grade::Close, String::new()),
            (Some(expected), other) => (
                Grade::Failed,
                format!("expected error {expected:?}, got {other:?}"),
            ),
            (None, Err(err)) => (Grade::Failed, format!("unexpected error {err}")),
            (None, Ok(layout)) => compare(db, &case, layout),
        };
        record(&mut tallies, &mut failures, &case, grade, &why);
    }
    let mut report = String::from("category/fontset: exact close failed\n");
    for ((category, fontset), tally) in &tallies {
        writeln!(
            report,
            "{category:>10} {fontset:>11}: {:4} {:4} {:4}",
            tally.exact, tally.close, tally.failed
        )
        .expect("write to string");
    }
    println!("{report}");
    for failure in failures.iter().take(60) {
        println!("{failure}");
    }
    assert!(
        failures.is_empty(),
        "{} mathtext cases differ",
        failures.len()
    );
}
